find_rule:
js:
var d = [];
var html = request(input);
var items = pdfa(html, ".short-drama-list .item, .drama-card");
for (var i = 0; i < items.length; i++) {
  var item = items[i];
  var title = pdfh(item, ".title&&Text");
  var cover = pd(item, "img&&data-src||img&&src", input);
  var url = pd(item, "a&&href", input);
  var epCount = pdfh(item, ".ep-count&&Text, .tag&&Text");
  if (title && url) {
    d.push({
      title: title.trim(),
      desc: epCount.trim(),
      pic_url: cover ? cover + '@Referer=' + input : '',
      url: url,
      col_type: 'movie_2'
    });
  }
}
setResult(d);

