detail_find_rule:
js:
var d = [];
var html = request(input);
var dramaTitle = pdfh(html, ".drama-header h1&&Text") || '微短剧';
var cover = pd(html, ".drama-cover img&&src", input);
var desc = pdfh(html, ".drama-desc&&Text");

// 1. 顶部大卡片 (注入剧名)
d.push({
  title: '剧名：' + dramaTitle,
  desc: desc,
  pic_url: cover ? cover + '@Referer=' + input : '',
  url: input,
  col_type: 'pic_1_card'
});

// 2. 短剧全集轻量列表 (通常为 80~120 集)
d.push({
  title: '【短剧全集·点击即播】',
  col_type: 'text_1'
});
var episodes = pdfa(html, ".episode-grid a, .drama-playlist a");
for (var i = 0; i < episodes.length; i++) {
  var ep = episodes[i];
  var epTitle = pdfh(ep, "Text") || ('第' + (i + 1) + '集');
  var epUrl = pd(ep, "a&&href", input);
  d.push({
    title: epTitle.trim(),
    url: 'lazy:' + epUrl,
    col_type: 'text_4'
  });
}
setResult(d);

lazy:
js:
var html = request(input);
var playUrl = '';
// 短剧直链常内嵌在 video 标签或者 JSON-LD 中
var match = html.match(/<video[^>]*src=["']([^"']+)["']/);
if (match && match[1]) {
  playUrl = match[1];
} else {
  var jsonMatch = html.match(/var\s+videoInfo\s*=\s*({[\s\S]*?});/);
  if (jsonMatch && jsonMatch[1]) {
    try {
      var info = JSON.parse(jsonMatch[1]);
      playUrl = info.video_url || info.url || '';
    } catch (e) {}
  }
}
if (!playUrl) playUrl = input;
if (playUrl.indexOf('http') !== 0) playUrl = 'https:' + playUrl;
playUrl = playUrl + ';{Referer@' + input + '&&User-Agent@Mobile};mp4';
setResult({ url: playUrl });
